import os, json
import re

d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

# Find the demo pair
for m in re.finditer(r'Demo pair \d+ input \d+x\d+:\n', t):
    end = m.end()
    # Read the grid (16 rows, 25 cols)
    rows = t[end:end+16*25+16].split('\n')  # 16 rows plus newlines

    input_grid = []
    for r_idx, r in enumerate(rows):
        if r_idx >= 16:
            break
        row_vals = [int(x) for x in r.split() if x.isdigit()]
        if len(row_vals) == 25:
            input_grid.append(row_vals)

    # Now find output following input
    output_start = m.end() + 16*25 + 16
    # Skip to "Demo pair ... output"
    for next_m in re.finditer(r'Demo pair \d+ output \d+x\d+:\n', t):
        if next_m.end() > output_start:
            output_start = next_m.end()
            break

    output_rows = t[output_start:output_start+16*25+16].split('\n')
    output_grid = []
    for r_idx, r in enumerate(output_rows):
        if r_idx >= 16:
            break
        row_vals = [int(x) for x in r.split() if x.isdigit()]
        if len(row_vals) == 25:
            output_grid.append(row_vals)

    print("Input rows with non-7s:")
    for r_idx, row in enumerate(input_grid):
        non_sevens = [(i, v) for i, v in enumerate(row) if v != 7]
        if non_sevens:
            print(f"  Row {r_idx}: {[(i,v) for i,v in non_sevens]}")

    print("\nOutput rows with non-7s:")
    for r_idx, row in enumerate(output_grid):
        non_sevens = [(i, v) for i, v in enumerate(row) if v != 7]
        if non_sevens:
            print(f"  Row {r_idx}: {[(i,v) for i,v in non_sevens]}")

