# Apply down-left transform (overwrite existing cells)
grid = [[4]*21 for _ in range(23)]
grid[14] = [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 5, 8, 4, 4, 4, 4, 4, 4, 4, 4]
grid[15] = [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 9, 2, 4, 4, 4, 4, 4, 4, 4, 4]
grid[16] = [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 9, 4, 4, 2, 4, 4, 4, 4, 4, 4, 4]

# Apply transform: 8s extend 2 steps down-left
for r in range(23):
    for c in range(21):
        if grid[r][c] == 8:
            for step in range(2):
                nr, nc = r + 1 + step, c - 1 - step
                if 0 <= nr < 23 and 0 <= nc < 21:
                    grid[nr][nc] = 8

# Submit
print(json.dumps({"action": "submit", "grid": grid}))

